  ["832513f8e27d7e14"] = { "ええ、その通りです、{class}。収集はすべて完了し、最後の戦争物資も一日以内にSilithusに届くはずです。聞くところによると、そこですべてが揃い、部隊の準備が整ったら、あなたがた英雄の中の誰かが、すでに組み上げたScepter of the Shifting Sandsを使って、Ahn'Qirajの外にある銅鑼を鳴らすそうです。それまであまり長く待たずに済むといいのですが。", "." },
  ["8325735e15ee5a47"] = { "%sは材料を集め、作業を始めた。", "." },
