  ["8371c2f988529cd4"] = { "%sは主人が危険にさらされている間は死ぬことを拒んだ！", "." },
  ["8375d2c5083050bc"] = { "そうだ、Winterspringの丘陵は今、再び始まったScourgeの猛攻に耐えようとしている。君の助けがあれば大いに助かるだろう。\n\n残っているNecropolisesの数: $2284W", "." },
  ["837b51080daaf5cb"] = { "まったくだよ! Brann、Rutgar、私、それにサルを合わせれば、38の言語が分かるんだから、なおさら奇妙だ。Titanの言葉も少し――VanirとAesirの両方ね。\n\nとにかく、彼女がカチカチ何を言っていたにせよ、「その場にいる」誰かに向けたものじゃなかったのは確かだ。それから彼女はうなずいて、攻撃に転じたんだ! いきなり襲いかかってきた!", "." },
  ["837d4c7785803cac"] = { "Azerothで、我らの民ほど苦しんだ種族は他にない、{class}。死を笑い飛ばすことは、我ら全員にとって第二の天性となったのだ。", "." },
  ["83959312ba26ef73"] = { "また一人愚か者が罠にかかったな！", "." },
