  ["83cae88f61b8c3d1"] = { "親父が言ってたよ。見知らぬ奴に話しかけられて、そいつを殺さないよう自分を抑えなきゃならない日が来るってな。", "." },
  ["83cd1439021a1375"] = { "もっといい匂いがしたら話してやるよ。コロンでもつけたらどうだ。", "." },
